package com.bank.report.service;
import com.bank.report.model.Account;
import com.bank.report.repository.AccountRepository;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import java.util.logging.*;

public class ReportService {
    private static final Logger log = Logger.getLogger(ReportService.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h); log.setLevel(Level.FINE);
    }
    private final AccountRepository repo;
    private int scans;
    public ReportService(AccountRepository repo) { this.repo = repo; }

    // SLOW: mimics correlated subquery — recompute avg per outer row
    public List<Account> slowCorrelated() {
        List<Account> all = repo.findAll(); scans = 0;
        List<Account> out = new ArrayList<>();
        for (Account a : all) {
            BigDecimal sum = BigDecimal.ZERO; int n = 0;
            for (Account x : all) { scans++; if (x.getBranch().equals(a.getBranch())) { sum = sum.add(x.getBalance()); n++; } }
            BigDecimal avg = sum.divide(BigDecimal.valueOf(n), 2, RoundingMode.HALF_UP);
            if (a.getBalance().compareTo(avg) > 0) out.add(a);
        }
        log.info(() -> "slowCorrelated scans=" + scans);
        return out;
    }

    // FAST: aggregate once (CTE), then join
    public List<Account> fastJoin() {
        List<Account> all = repo.findAll(); scans = 0;
        Map<String, BigDecimal> sum = new HashMap<>(); Map<String, Integer> cnt = new HashMap<>();
        for (Account x : all) { scans++; sum.merge(x.getBranch(), x.getBalance(), BigDecimal::add); cnt.merge(x.getBranch(), 1, Integer::sum); }
        List<Account> out = new ArrayList<>();
        for (Account a : all) {
            scans++;
            BigDecimal avg = sum.get(a.getBranch()).divide(BigDecimal.valueOf(cnt.get(a.getBranch())), 2, RoundingMode.HALF_UP);
            if (a.getBalance().compareTo(avg) > 0) out.add(a);
        }
        log.info(() -> "fastJoin scans=" + scans);
        return out;
    }
}
