package com.bank.report;
import com.bank.report.model.Account;
import com.bank.report.repository.AccountRepository;
import com.bank.report.service.ReportService;
import java.util.logging.*;

public class ReportDemo {
    public static void main(String[] args) {
        ReportService svc = new ReportService(new AccountRepository());
        System.out.println("Correlated -> " + svc.slowCorrelated().stream().map(Account::getId).toList());
        System.out.println("JOIN       -> " + svc.fastJoin().stream().map(Account::getId).toList());
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
